      "unwrap",
      "wrap"
    ],
    "justification": "These functions are included because they interact with the state exposed during the risky call in claimInactiveAccountDividends."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "claimDividends",
      "unwrap",
      "wrap"
    ],
    "nesting_bound": {
      "claimDividends": 1,
      "unwrap": 1,
      "wrap": 1
    }
