    "function": "claimInactiveAccountDividends",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "_sum__balances",
      "sol_type": "uint256",
      "meaning": "Tracks the sum of all balances in the _balances mapping.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances == _totalSupply",
    "stable_formula": "_sum__balances == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances == _totalSupply",
    "rule": "The target property is maintained as an invariant across the callback window, ensuring conservation of total supply against balances."
  }
}
